int currentIndex = 0;
int decodedIndex = 0;
TreeNode* current = root;

while (currentIndex < encLen && decodedIndex < decLen) {
    if (encoded[currentIndex] == 0) {
        current = current->left;
    } else {
        current = current->right;
    }

    if (current->left == nullptr && current->right == nullptr) {
        decoded[decodedIndex++] = current->data;
        current = root;
    }

    currentIndex++;
}

decLen = decodedIndex;

